program='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Mark solid blocks at least 5 cells tall and 5 cells wide.
    for r in range(rows - 4):
        for c in range(cols - 4):
            color = grid[r][c]
            if all(grid[i][j] == color
                   for i in range(r, r + 5)
                   for j in range(c, c + 5)):
                for i in range(r, r + 5):
                    for j in range(c, c + 5):
                        out[i][j] = 4
    return out
'''
